class StreamChecker {
    struct Node {
        Node* children[26];
        bool isEnd;
        Node() {
            for (int i = 0; i < 26; i++) children[i] = nullptr;
            isEnd = false;
        }
    };
    Node* root;
    string buffer;
    int maxLen;
public:
    StreamChecker(vector<string>& words) {
        root = new Node();
        maxLen = 0;
        for (const string& w : words) {
            maxLen = max(maxLen, (int)w.size());
            Node* cur = root;
            for (int i = (int)w.size() - 1; i >= 0; i--) {
                int c = w[i] - 'a';
                if (!cur->children[c]) cur->children[c] = new Node();
                cur = cur->children[c];
            }
            cur->isEnd = true;
        }
    }

    bool query(char letter) {
        buffer.push_back(letter);
        if ((int)buffer.size() > maxLen) buffer.erase(buffer.begin());
        Node* cur = root;
        for (int i = (int)buffer.size() - 1; i >= 0; i--) {
            int c = buffer[i] - 'a';
            if (!cur->children[c]) return false;
            cur = cur->children[c];
            if (cur->isEnd) return true;
        }
        return false;
    }
};
